#define ARRAY_COUNT(array) (sizeof(array) / sizeof((array)[0]))

static const struct city_city_data_s *city_data(
    size_t province_index, size_t city_index)
{
    const struct city_province_data_s *province;

    if (province_index >= ARRAY_COUNT(g_provinces)) {
        return NULL;
    }

    province = &g_provinces[province_index];
    if (city_index >= province->city_count) {
        return NULL;
    }

    return &g_cities[province->first_city + city_index];
}

size_t openvela_ui_city_province_count(void)
{
    return ARRAY_COUNT(g_provinces);
}

const char *openvela_ui_city_province_name(size_t province_index)
{
    if (province_index >= ARRAY_COUNT(g_provinces)) {
        return g_empty_string;
    }

    return g_provinces[province_index].name;
}

size_t openvela_ui_city_city_count(size_t province_index)
{
    if (province_index >= ARRAY_COUNT(g_provinces)) {
        return 0;
    }

    return g_provinces[province_index].city_count;
}

const char *openvela_ui_city_city_name(size_t province_index,
                                       size_t city_index)
{
    const struct city_city_data_s *city =
        city_data(province_index, city_index);

    return city ? city->name : g_empty_string;
}

const char *openvela_ui_city_city_short_name(size_t province_index,
                                             size_t city_index)
{
    const struct city_city_data_s *city =
        city_data(province_index, city_index);

    return city ? city->short_name : g_empty_string;
}

const char *openvela_ui_city_city_location_id(size_t province_index,
                                              size_t city_index)
{
    const struct city_city_data_s *city =
        city_data(province_index, city_index);

    return city ? city->location_id : g_empty_string;
}

size_t openvela_ui_city_district_count(size_t province_index,
                                       size_t city_index)
{
    const struct city_city_data_s *city =
        city_data(province_index, city_index);

    return city ? city->district_count : 0;
}

const char *openvela_ui_city_district_name(size_t province_index,
                                           size_t city_index,
                                           size_t district_index)
{
    const struct city_city_data_s *city =
        city_data(province_index, city_index);

    if (!city || district_index >= city->district_count) {
        return g_empty_string;
    }

    return g_districts[city->first_district + district_index];
}
